def build_agent(sandbox):
    # Upper beams for large/medium separation
    beam1 = sandbox.add_static_beam(x=5.63, y=2.4, width=0.6, height=0.08, density=8.5)
    sandbox.set_material_properties(beam1, restitution=0.0)
    beam2 = sandbox.add_static_beam(x=6.47, y=2.4, width=0.6, height=0.08, density=8.5)
    sandbox.set_material_properties(beam2, restitution=0.0)

    # Lower beam to prevent medium particles from falling into small zone
    beam3 = sandbox.add_static_beam(x=6.05, y=1.92, width=1.0, height=0.08, density=8.5)
    sandbox.set_material_properties(beam3, restitution=0.0)

    return beam1  # Return a representative beam


def agent_action(sandbox, agent_body, step_count):
    if step_count % 32 != 0:
        return

    # Nudge small particles downward if they are above the small zone
    for p in sandbox.get_particles_small():
        if p.active and p.position.y > 1.92:
            sandbox.apply_force(p, (0, -30.0))

    # Nudge medium particles upward if they are below the sieve band
    for p in sandbox.get_particles_medium():
        if p.active and p.position.y < 2.52:
            if p.position.y < 1.92:
                sandbox.apply_force(p, (0, 25.5))
